20	/** Minimal company access check using fields available on ActorContext. */
21	function assertCompanyAccessCtx(ctx: RequestCtx, companyId: string) {
22	  if (!ctx.actor) throw unauthorized();
23	  if (ctx.actor.type === "agent" && ctx.actor.companyId !== companyId) {
24	    throw forbidden("Agent key cannot access another company");
25	  }
26	  // Board actor company-list enforcement is handled by the Express auth
27	  // middleware before the Handler is reached.
28	  // TODO(cloudflare): re-enforce companyIds list in Workers auth layer.
29	}
