31	function buildHandlers(
32	  db: Db,
33	  options: { pluginWorkerManager?: PluginWorkerManager } = {},
34	) {
35	  const svc = routineService(db, { pluginWorkerManager: options.pluginWorkerManager });
36	  const access = accessService(db);
37	
38	  async function assertBoardCanAssignTasks(ctx: RequestCtx, companyId: string) {
39	    assertCompanyAccessCtx(ctx, companyId);
40	    if (ctx.actor?.type !== "board") return;
41	    // TODO(cloudflare): ctx.actor lacks `source` and `isInstanceAdmin`; the
42	    // local_implicit / isInstanceAdmin fast-path is not available.
43	    // Full permission check via access service is used for all board actors.
44	    const allowed = await access.canUser(companyId, ctx.actor.userId, "tasks:assign");
45	    if (!allowed) {
46	      throw forbidden("Missing permission: tasks:assign");
47	    }
48	  }
49	
50	  function assertCanManageCompanyRoutine(ctx: RequestCtx, companyId: string, assigneeAgentId?: string | null) {
51	    assertCompanyAccessCtx(ctx, companyId);
52	    if (ctx.actor?.type === "board") return;
53	    if (ctx.actor?.type !== "agent" || !ctx.actor.agentId) throw unauthorized();
54	    if (assigneeAgentId !== ctx.actor.agentId) {
55	      throw forbidden("Agents can only manage routines assigned to themselves");
56	    }
57	  }
58	
59	  async function assertCanManageExistingRoutine(ctx: RequestCtx, routineId: string) {
60	    const routine = await svc.get(routineId);
61	    if (!routine) return null;
62	    assertCompanyAccessCtx(ctx, routine.companyId);
63	    if (ctx.actor?.type === "board") return routine;
64	    if (ctx.actor?.type !== "agent" || !ctx.actor.agentId) throw unauthorized();
65	    if (routine.assigneeAgentId !== ctx.actor.agentId) {
66	      throw forbidden("Agents can only manage routines assigned to themselves");
67	    }
68	    return routine;
69	  }
