80	  const createRoutine: Handler = async (ctx) => {
81	    const companyId = ctx.param("companyId") ?? "";
82	    const body = await ctx.json();
83	    const parsed = createRoutineSchema.parse(body);
84	    await assertBoardCanAssignTasks(ctx, companyId);
85	    assertCanManageCompanyRoutine(ctx, companyId, parsed.assigneeAgentId);
86	    const created = await svc.create(companyId, parsed, {
87	      agentId: ctx.actor?.type === "agent" ? (ctx.actor.agentId ?? null) : null,
88	      userId: ctx.actor?.type === "board" ? (ctx.actor.userId ?? "board") : null,
89	    });
90	
91	    // ctx.actor lacks `runId`; log with null runId.
92	    // TODO(cloudflare): thread runId through ActorContext.
93	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
94	    const actorId = ctx.actor!.type === "agent"
95	      ? (ctx.actor!.agentId ?? "unknown-agent")
96	      : (ctx.actor!.userId ?? "board");
97	    await logActivity(db, {
98	      companyId,
99	      actorType,
100	      actorId,
101	      agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
102	      runId: null,
103	      action: "routine.created",
104	      entityType: "routine",
105	      entityId: created.id,
106	      details: { title: created.title, assigneeAgentId: created.assigneeAgentId },
107	    });
108	    const telemetryClient = getTelemetryClient();
109	    if (telemetryClient) {
110	      trackRoutineCreated(telemetryClient);
111	    }
112	    return Response.json(created, { status: 201 });
113	  };
