127	  const patchRoutine: Handler = async (ctx) => {
128	    const id = ctx.param("id") ?? "";
129	    const routine = await assertCanManageExistingRoutine(ctx, id);
130	    if (!routine) {
131	      return Response.json({ error: "Routine not found" }, { status: 404 });
132	    }
133	    const body = await ctx.json();
134	    const parsed = updateRoutineSchema.parse(body);
135	    const assigneeWillChange =
136	      parsed.assigneeAgentId !== undefined &&
137	      parsed.assigneeAgentId !== routine.assigneeAgentId;
138	    if (assigneeWillChange) {
139	      await assertBoardCanAssignTasks(ctx, routine.companyId);
140	    }
141	    const statusWillActivate =
142	      parsed.status !== undefined &&
143	      parsed.status === "active" &&
144	      routine.status !== "active";
145	    if (statusWillActivate) {
146	      await assertBoardCanAssignTasks(ctx, routine.companyId);
147	    }
148	    if (
149	      ctx.actor?.type === "agent" &&
150	      parsed.assigneeAgentId !== undefined &&
151	      parsed.assigneeAgentId !== ctx.actor.agentId
152	    ) {
153	      throw forbidden("Agents can only assign routines to themselves");
154	    }
155	    const updated = await svc.update(routine.id, parsed, {
156	      agentId: ctx.actor?.type === "agent" ? (ctx.actor.agentId ?? null) : null,
157	      userId: ctx.actor?.type === "board" ? (ctx.actor.userId ?? "board") : null,
158	    });
159	
160	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
161	    const actorId = ctx.actor!.type === "agent"
162	      ? (ctx.actor!.agentId ?? "unknown-agent")
163	      : (ctx.actor!.userId ?? "board");
164	    await logActivity(db, {
165	      companyId: routine.companyId,
166	      actorType,
