400	export function routineRoutes(
401	  db: Db,
402	  options: { pluginWorkerManager?: PluginWorkerManager } = {},
403	) {
404	  const router = Router();
405	  const {
406	    listRoutines,
407	    createRoutine,
408	    getRoutine,
409	    patchRoutine,
410	    listRoutineRuns,
411	    createRoutineTrigger,
412	    patchRoutineTrigger,
413	    deleteRoutineTrigger,
414	    rotateRoutineTriggerSecret,
415	    runRoutine,
416	    firePublicTrigger,
417	  } = buildHandlers(db, options);
418	
419	  const storageSentinel = new Proxy({} as StorageService, {
420	    get(_target, prop) {
421	      throw new Error(`routine handler unexpectedly accessed storage.${String(prop)}`);
422	    },
423	  });
424	  const deps = { db, storage: storageSentinel };
425	
426	  router.get("/companies/:companyId/routines", expressHandler(listRoutines, deps));
427	  router.post("/companies/:companyId/routines", expressHandler(createRoutine, deps));
428	  router.get("/routines/:id", expressHandler(getRoutine, deps));
429	  router.patch("/routines/:id", expressHandler(patchRoutine, deps));
430	  router.get("/routines/:id/runs", expressHandler(listRoutineRuns, deps));
431	  router.post("/routines/:id/triggers", expressHandler(createRoutineTrigger, deps));
432	  router.patch("/routine-triggers/:id", expressHandler(patchRoutineTrigger, deps));
433	  router.delete("/routine-triggers/:id", expressHandler(deleteRoutineTrigger, deps));
434	  router.post("/routine-triggers/:id/rotate-secret", expressHandler(rotateRoutineTriggerSecret, deps));
435	  router.post("/routines/:id/run", expressHandler(runRoutine, deps));
436	  router.post("/routine-triggers/public/:publicId/fire", expressHandler(firePublicTrigger, deps));
437	
438	  return router;
439	}
